const art=(bg,shapes)=>`<svg viewBox="0 0 400 300" role="img" aria-label="物品预置示意图"><rect width="400" height="300" fill="${bg}"/><ellipse cx="200" cy="262" rx="96" ry="14" fill="#00000010"/>${shapes}</svg>`;
const arts={plant:art('#e5e9dc','<path d="M155 193h92l-15 66h-64z" fill="#b98569"/><path d="M200 204V91m0 70-48-34m48 62 47-53" stroke="#56724a" stroke-width="7" fill="none"/><ellipse cx="171" cy="103" rx="28" ry="57" transform="rotate(-42 171 103)" fill="#7b9867"/><ellipse cx="228" cy="98" rx="27" ry="56" transform="rotate(40 228 98)" fill="#537b50"/><ellipse cx="143" cy="144" rx="23" ry="44" transform="rotate(-54 143 144)" fill="#809a6b"/><ellipse cx="249" cy="147" rx="24" ry="44" transform="rotate(53 249 147)" fill="#64895a"/>'),lamp:art('#ece4d5','<path d="M202 254V126" stroke="#88816d" stroke-width="8"/><ellipse cx="202" cy="254" rx="57" ry="11" fill="#a29a82"/><path d="M143 77h122l27 80H116z" fill="#f9f3df"/><ellipse cx="204" cy="157" rx="88" ry="10" fill="#d5cba6"/>'),books:art('#e3e7e9','<path d="M106 211h204v42H106z" fill="#778c86"/><path d="M117 176h177v36H117z" fill="#c39b73"/><path d="M99 134h198v43H99z" fill="#526b70"/><path d="M125 91h154v44H125z" fill="#dec29f"/><path d="M136 100h128v25H136zM110 143h169v25H110zM127 186h150v17H127zM117 221h178v22H117z" fill="#f7f0e3"/>'),cooker:art('#e6e3df','<rect x="78" y="87" width="244" height="164" rx="15" fill="#343c37"/><rect x="89" y="97" width="222" height="140" rx="9" fill="#4e564c"/><ellipse cx="200" cy="159" rx="67" ry="47" fill="none" stroke="#91998b" stroke-width="2"/><ellipse cx="200" cy="159" rx="50" ry="35" fill="none" stroke="#91998b"/><path d="M125 218h27m96 0h26" stroke="#a9b09f" stroke-width="3"/><rect x="182" y="210" width="35" height="13" rx="3" fill="#b69a78"/>')};
const items=[{title:'搬家转让 · 龟背竹',price:'免费送',type:'FREE',art:'plant',building:'3 栋',time:'2 小时前',want:5},{title:'陪我读书的暖光台灯',price:'¥ 35',type:'FIXED',art:'lamp',building:'6 栋',time:'5 小时前',want:2},{title:'周末读物，送给爱看书的你',price:'随便给',type:'FLEXIBLE',art:'books',building:'2 栋',time:'昨天',want:3},{title:'搬家闲置电磁炉',price:'¥ 50',type:'FIXED',art:'cooker',building:'5 栋',time:'昨天',want:4}];
let filter='ALL',query='',wanted=false,trade='confirmed';const app=document.getElementById('app');
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.hidden=false;setTimeout(()=>el.hidden=true,2800)}
function cards(){const list=items.filter(x=>(filter==='ALL'||x.type===filter)&&x.title.includes(query));document.getElementById('cards').innerHTML=list.length?list.map(x=>`<a href="#detail" aria-label="查看详情示例"><div class="art">${arts[x.art]}<span class="badge">${x.time.includes('小时')?'刚上架':'新上架'} · 示意图</span></div><div class="price">${x.price}</div><h3>${x.title}</h3><div class="meta"><span>${x.building} · ${x.time}</span><span>${x.want} 位邻居想要</span></div></a>`).join(''):'<p class="muted">没有找到符合条件的物品。</p>'}
function home(){return `<div class="head"><div><p class="eyebrow">青禾里社区 · 邻里集市</p><h1>看看附近，有什么好东西</h1><span class="muted">就在隔壁楼，让闲置继续被需要。</span></div><button class="primary" onclick="location.hash='publish'">＋ 发布闲置</button></div><div class="stats"><span><b>28</b>本月发布</span><span><b>16</b>本月成交</span><span><b>12</b>当前在售 · 含预约</span></div><div class="searchbar"><input aria-label="搜索闲置" placeholder="搜索物品，比如绿植、书籍、电磁炉" oninput="query=this.value;cards()"><div class="filters">${[['ALL','全部'],['FREE','免费送'],['FLEXIBLE','随便给'],['FIXED','标价']].map(([v,l])=>`<button class="${filter===v?'active':''}" onclick="filter='${v}';render()">${l}</button>`).join('')}</div></div><div id="cards" class="grid"></div><div class="foot"><span>最快送出：儿童绘本 · 32 分钟</span><span>最想要：龟背竹 · 5 人想要</span><span>统计均为原型示例数据</span></div>`}
function detail(){return `<a href="#home" class="back">← 返回邻里集市</a><div class="detail"><section><div class="art">${arts.plant}<span class="badge">物品示意图</span></div><div class="comments"><h2>邻居留言 <span class="muted">2</span></h2><div class="comment"><b>周橙 · 6 栋</b><span>花盆一起送吗？放阳台合适吗？</span></div><div class="comment"><b>苏苏 · 发布者</b><span>花盆一起送，平时放在散射光充足的地方就好。</span></div><div class="commentform"><input id="comment" aria-label="留言内容" placeholder="想了解什么，问问邻居…"><button onclick="toast(document.getElementById('comment').value?'留言已在原型中提交，未写入数据库':'请先填写留言')">留言</button></div></div></section><section><span class="tag">刚上架 · 可领取</span><h1>搬家转让 · 龟背竹</h1><div class="price">免费送</div><p>养了半年，很好打理，最近又长出了新叶子。<br>因为搬家带不走，想给它找一位新邻居。<br>花盆一起送，请自备袋子，楼下自提就好。</p><div class="profile"><span class="avatar">苏</span><div>苏苏<div class="muted">青禾里 · 3 栋</div></div></div><div class="line"></div><dl class="facts"><dt>物品状态</dt><dd>可领取</dd><dt>交接方式</dt><dd>社区内自提，时间可协商</dd><dt>发布时间</dt><dd>今天 10:30 · 示例</dd><dt>意向人数</dt><dd>${wanted?6:5} 位邻居想要</dd></dl><div class="actions"><button class="primary" onclick="wanted=!wanted;render();toast('意向状态已在原型中更新')">${wanted?'撤回意向':'我想要'}</button><button class="outline" onclick="location.hash='handoff'">交接流程示例</button></div><p class="tiny">想要后，由发布者选择领取人并发起预约。</p></section></div>`}
function publish(){return `<a href="#home" class="back">← 返回邻里集市</a><div class="head"><div><h1>把闲置交给下一位邻居</h1><span class="muted">说明真实情况，交接会更顺利。</span></div></div><div class="columns"><form class="sheet" onsubmit="event.preventDefault();toast('发布流程演示完成；未保存业务数据')"><div class="field"><label for="title">物品名称</label><input id="title" value="搬家闲置电磁炉" required maxlength="60"></div><div class="field"><label for="description">物品描述</label><textarea id="description" required>电磁炉用了两年，功能正常，表面有点划痕，搬家不要了。</textarea></div><div class="two"><div class="field"><label for="mode">交易方式</label><select id="mode" onchange="document.getElementById('price').disabled=this.value!=='标价'"><option>免费送</option><option>随便给</option><option selected>标价</option></select></div><div class="field"><label for="price">期望价格（元）</label><input id="price" type="number" min="0.01" step="0.01" value="50"></div></div><div class="two"><div class="field"><label for="building">自提楼栋</label><input id="building" value="3 栋" required></div><div class="field"><label>预置图片</label><div class="photo">${arts.cooker}</div></div></div><button type="submit" class="primary">确认发布</button></form><aside class="ai"><div class="aihead"><h2>AI 帮我整理</h2><span class="tag">固定示例</span></div><p class="muted">从你提供的事实出发，把物品说明写清楚。</p><button class="outline" onclick="toast('已展示固定示例，未调用真实模型')">查看建议示例</button><div class="suggestion"><h3>建议描述</h3><p id="suggested">电磁炉使用两年，功能正常，表面有轻微划痕。因搬家转让，适合有需要的邻居自提。</p><button class="outline" onclick="document.getElementById('description').value=document.getElementById('suggested').textContent;toast('已采用示例文案')">采用文案</button><div class="line"></div><span class="muted">参考定价区间</span><p class="range">¥ 30 — 60</p><p class="tiny">固定原型示例，非市场行情估价。<br>实际功能还需补充品牌、型号等信息。</p><button class="outline" onclick="document.getElementById('mode').value='标价';document.getElementById('price').disabled=false;document.getElementById('price').value=30;toast('已填入下限，可自行修改')">采用参考价格</button></div></aside></div>`}
function handoff(){let done=trade==='completed',cancelled=trade==='cancelled';return `<div class="head"><div><p class="eyebrow">我的 · 交接事项</p><h1>${done?'闲置有了新的主人':cancelled?'预约已取消':'和邻居约好了'}</h1><span class="muted">当前示例身份：发布者 · 时间、地点和进度都在这里。</span></div><span class="tag">${done?'已完成':cancelled?'已取消':'1 件待交接'}</span></div><div class="progress"><span class="done">✓ 已表达想要</span><span class="done">✓ 已发起预约</span><span class="done">✓ 领取人已确认</span><span>${done?'✓ 已完成':'④ 等待交接'}</span></div><div class="handoff"><section class="sheet"><div class="tradehead"><div class="thumb">${arts.cooker}</div><div><span class="tag">${done?'已送出':cancelled?'可领取':'已预约'}</span><h2 style="margin:12px 0 6px">搬家闲置电磁炉</h2><span class="muted">¥ 50 · 领取人：周橙（6 栋）</span></div></div><div class="line"></div><span class="muted">约定交接时间 · 示例</span><p class="time">9 月 28 日 19:00 — 20:00</p><dl class="facts"><dt>交接地点</dt><dd>青禾里 3 栋楼下门厅</dd><dt>发布者</dt><dd>林小满 · 3 栋</dd><dt>领取者</dt><dd>周橙 · 6 栋</dd><dt>交易状态</dt><dd>${done?'交接完成':cancelled?'预约取消，恢复可领取':'双方已确认，等待线下交接'}</dd></dl>${trade==='confirmed'?`<div class="actions"><button class="primary" onclick="if(confirm('确认完成线下交接？此处仅模拟状态。')){trade='completed';render()}">确认已送出</button><button class="outline" onclick="trade='cancelled';render()">取消预约</button></div>`:`<div class="actions"><button onclick="trade='confirmed';render()">重置原型示例</button></div>`}</section><aside class="aside"><h2>交接前的小提醒</h2><p>确认时间再出门，尽量选择楼栋门厅等公共区域交接。</p><div class="line"></div><h3>时间不合适？</h3><p>可以取消本次预约，再由发布者选择新的时间。取消后恢复为可领取。</p><div class="line"></div><h3>物品已送出？</h3><p>实际产品中，确认后将同时更新物品和交易状态，并保留历史记录。</p><p class="tiny">此页为界面状态模拟，不产生真实交易。</p></aside></div>`}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('[data-route]').forEach(x=>x.classList.toggle('active',x.dataset.route===route));app.innerHTML=({home,detail,publish,handoff}[route]||home)();if(route==='home'){document.querySelector('[aria-label="搜索闲置"]').value=query;cards()}window.scrollTo(0,0)}
window.addEventListener('hashchange',render);render();
